// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"bitcoin-halving":{"slug":"bitcoin-halving","cat":"basics","en":"Bitcoin halving","contentLocale":"tr","term":"Bitcoin halving (yarılanma)","aka":["halving","yarılanma","Bitcoin yarılanması"],"short":"Bitcoin halving (yarılanma), yaklaşık her dört yılda bir, yani her 210.000 blokta bir, madencilere verilen blok ödülünün kod gereği yarıya indirildiği olaydır.","body":[[["Bitcoin","bitcoin"],"'de yeni BTC yalnızca blok ödülüyle ortaya çıkar. 2009'da ödül blok başına 50 BTC'ydi; ardından 25, 12,5 ve 6,25 BTC'ye indi. Nisan 2024 halving'inden sonra blok ödülü 3,125 BTC oldu. Bu takvim, toplam arzın 21 milyon BTC'yi aşmamasını sağlar."],"Halving, piyasaya giren yeni BTC miktarını, yani madencilerin satabileceği yeni arzı azaltır. Madencilerin geliri bir gecede yarıya iner; bu da verimsiz madencileri zorlayabilir ve işlem ücretlerinin gelir içindeki payını artırır.","Geçmişte halving'lerin ardından güçlü yükseliş dönemleri yaşandı ve bu yüzden olay piyasada çok konuşulur. Ancak fiyatı birçok etken belirler; geçmişteki örüntülerin tekrarlanacağına dair bir garanti yoktur."],"example":["Bitcoin'de ortalama her 10 dakikada bir blok üretilir; bu da günde yaklaşık 144 blok demektir. Halving'den önce blok ödülü 6,25 BTC iken günlük yeni arz 144 x 6,25 = 900 BTC'ydi. Nisan 2024'ten sonra ödül 3,125 BTC olunca günlük yeni arz 144 x 3,125 = 450 BTC'ye indi. BTC 60.000 ",["USDT","usdt"]," ise madencilerin günlük blok ödülü geliri 54 milyon USDT'den 27 milyon USDT'ye düşer."],"mistakes":["Halving'in BTC fiyatını otomatik olarak ikiye katladığını düşünmek.","Halving'in mevcut BTC bakiyenizi veya cüzdanınızdaki coinleri etkilediğini sanmak.","Halving tarihinin kesin bir gün olduğunu varsaymak; tarih blok yüksekliğine bağlıdır ve tahminidir."],"faq":[{"q":"Bir sonraki Bitcoin halving ne zaman?","a":"Halving her 210.000 blokta bir gerçekleşir; bu yaklaşık dört yıla denk gelir. Nisan 2024'ten sonraki halving'in 2028 civarında olması beklenir, kesin tarih blok üretim hızına bağlıdır."},{"q":"Tüm Bitcoin'ler ne zaman çıkarılmış olacak?","a":"Ödül her halving'de yarıya indiği için son satoshi'lerin 2140 civarında üretilmesi beklenir. Bundan sonra madenciler yalnızca işlem ücretlerinden gelir elde eder."}],"title":"Bitcoin halving nedir? Yarılanma nasıl çalışır?","description":"Bitcoin halving'in ne olduğunu, blok ödülünün nasıl yarıya indiğini ve madencileri ile yeni arzı nasıl etkilediğini öğrenin.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC), 2009'da Satoshi Nakamoto takma adıyla başlatılan, iş ispatı ile çalışan ve toplam arzı 21 milyon BTC ile sınırlı olan ilk ve piyasa değeri en büyük kripto paradır."],["mining","Kripto madenciliği (mining)","Kripto madenciliği, iş ispatı kullanan blockchain'lerde özel donanımlarla hesaplama yapılarak işlemlerin bloklara eklenmesi ve karşılığında yeni basılan coin ile işlem ücretlerinin kazanılması sürecidir."],["proof-of-work","İş ispatı (Proof of Work, PoW)","İş ispatı (Proof of Work, PoW), madencilerin zor bir matematik bulmacasını çözmek için bilgi işlem gücü harcadığı ve bulmacayı ilk çözenin yeni bloğu ekleyip ödül kazandığı bir blockchain uzlaşma mekanizmasıdır."],["hash-rate","Hash oranı (hash rate)","Hash oranı, iş ispatı (proof of work) kullanan bir ağda madencilerin saniyede yaptığı toplam hash hesaplama sayısıdır ve ağın işlem gücünü ve güvenliğini gösterir."],["satoshi","Satoshi (sats)","Satoshi (sats), Bitcoin'in en küçük birimidir; 1 BTC 100.000.000 satoshi'ye eşittir ve adını Bitcoin'in takma adlı yaratıcısı Satoshi Nakamoto'dan alır."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"stop-loss":{"slug":"stop-loss","cat":"trading","en":"Stop-loss order","contentLocale":"tr","term":"Zarar durdur (stop-loss) emri","aka":["stop-loss","stop loss","zarar kes","stop"],"short":"Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir.","body":[["Zarar durdur emri iki parçadan oluşur: tetik fiyatı ve tetiklendikten sonra gönderilecek emir. Stop-market türünde tetiklenen emir ",["piyasa emri","market-order"]," olarak gider ve hemen dolar ama ",["kayma","slippage"]," olabilir. Stop-limit türünde ise ",["limit emir","limit-order"]," gider; fiyat garantisi vardır ama hızlı düşüşte dolmayabilir."],["Vadeli işlemlerde tetik fiyatının ",["son işlem","last-price"]," fiyatına mı yoksa mark (işaret) fiyatına mı bakacağını seçebilirsiniz. Borsalar bu seçenekleri farklı adlarla sunar. Kaldıraçlı pozisyonlarda zarar durdur, ",["likidasyon","liquidation"]," seviyesinden önce çıkmanızı sağlayan temel araçtır."],"Zarar durdur seviyesini rastgele bir yüzdeyle değil, işlem fikrinizin geçersiz olduğu fiyata göre belirlemek daha mantıklıdır. Ardından pozisyon büyüklüğünü, bu seviyede kaybedeceğiniz tutar kabul edebileceğiniz sınırda kalacak şekilde ayarlarsınız."],"example":["Hesabınız 5.000 ",["USDT","usdt"]," ve her işlemde en fazla yüzde 1, yani 50 USDT kaybetmeyi kabul ediyorsunuz. Bir coini 40 USDT'den almak istiyor, zarar durdurunuzu 38 USDT'ye koyuyorsunuz; coin başına risk 2 USDT. Pozisyon büyüklüğü 50 / 2 = 25 coin, yani 1.000 USDT'lik alım olur. Fiyat 38'e düşerse emir tetiklenir; stop-market emri kayma ile örneğin 37,9'dan dolarsa kaybınız 52,5 USDT olur, planladığınıza çok yakın."],"mistakes":["Zarar durdur seviyesini fiyata çok yakın koyup sıradan dalgalanmalarla pozisyondan atılmak.","Fiyat stop seviyesine yaklaşınca emri iptal edip daha aşağıya çekmek.","Stop-limit emrin hızlı düşüşte hiç dolmayabileceğini bilmeden kullanmak."],"faq":[{"q":"Stop-loss her zaman belirlediğim fiyattan mı çalışır?","a":"Hayır. Stop-market emri tetik seviyesine gelindiğinde piyasa emriyle dolar ve hızlı hareketlerde daha kötü fiyattan gerçekleşebilir. Stop-limit ise fiyat garantisi verir ama dolmayabilir."},{"q":"Stop-loss nereye konmalı?","a":"İşlem gerekçenizin geçersiz olduğu fiyat seviyesine konması yaygın bir yaklaşımdır. Pozisyon büyüklüğünü de bu seviyedeki kaybın kabul edilebilir kalacağı şekilde ayarlamak gerekir."}],"title":"Stop-loss (zarar durdur) nedir? Nasıl kullanılır?","description":"Zarar durdur emrinin nasıl çalıştığını, stop-market ve stop-limit farkını ve pozisyon büyüklüğüyle birlikte nasıl kullanılacağını öğrenin.","related":[["take-profit","Kâr al (take-profit) emri","Kâr al (take-profit) emri, fiyat önceden belirlediğiniz hedef seviyeye ulaştığında pozisyonunuzu otomatik olarak kapatarak kârı gerçekleştiren emirdir."],["stop-limit-order","Stop-limit emir","Stop-limit emir, fiyat belirlediğiniz tetik (stop) seviyesine ulaştığında, önceden tanımladığınız fiyattan bir limit emir gönderen ve böylece kötü fiyattan dolmayı engelleyen koşullu bir emirdir."],["trailing-stop","İz süren stop (trailing stop)","İz süren stop (trailing stop), fiyat lehinize hareket ettikçe tetik seviyesini otomatik olarak belirli bir yüzde veya tutar kadar geriden takip ettiren, fiyat geri döndüğünde ise pozisyonu kapatan bir emirdir."],["position-sizing","Pozisyon büyüklüğü (Position sizing)","Pozisyon büyüklüğü, bir işleme ne kadar sermaye ayıracağınızı zarar durdur seviyenize ve kabul edebileceğiniz en yüksek kayba göre belirleme yöntemidir."],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Kâr al ve zarar durdur plandır, sigorta değil"},"coin":null,"tool":"/liquidations","cta":false},"unrealized-pnl":{"slug":"unrealized-pnl","cat":"derivatives","en":"Unrealized PnL","contentLocale":"tr","term":"Gerçekleşmemiş kâr/zarar (Unrealized PnL)","aka":["gerçekleşmemiş PnL","unrealized PnL","kâğıt üzerindeki kâr","açık pozisyon kârı"],"short":"Gerçekleşmemiş kâr/zarar (unrealized PnL), açık bir pozisyonun mevcut fiyata göre hesaplanan ama pozisyon kapatılmadığı için henüz kesinleşmemiş kâr veya zararıdır.","body":["Pozisyonunuz açık olduğu sürece kâr veya zarar fiyatla birlikte sürekli değişir. Pozisyonu kapattığınızda bu tutar gerçekleşmiş kâr/zarara (realized PnL) dönüşür ve bakiyenize kesin olarak yansır. Vadeli işlemlerde gerçekleşmemiş kâr-zarar genellikle son fiyata göre değil, işaret fiyatına göre hesaplanır.",["Gerçekleşmemiş kâr-zarar teminat bakiyenizi doğrudan etkiler. Zarar büyüdükçe teminat oranınız düşer ve ",["likidasyon","liquidation"]," fiyatına yaklaşırsınız. Çapraz marjinde ise bir pozisyondaki gerçekleşmemiş kâr diğer pozisyonlar için ek teminat görevi görebilir; o kâr fiyat dönünce kaybolursa diğer pozisyonlar da birden riskli hâle gelebilir."],"Borsalar kâr-zararı hem tutar hem yüzde olarak gösterir. Yüzde, genellikle pozisyonun değerine değil teminata göre hesaplanır; bu yüzden kaldıraçlı pozisyonlarda büyük rakamlar görmek olağandır. Kapanışta ödenecek ücretler ve fonlama ödemeleri gerçekleşmiş sonucu biraz değiştirir."],"example":[["BTC","bitcoin"]," 58.000 ",["USDT","usdt"]," iken 0,3 BTC long açtınız ve 6x kaldıraçla 2.900 USDT teminat bağladınız. ",["İşaret fiyatı","mark-price"]," 61.000 USDT'ye çıktığında gerçekleşmemiş kârınız 0,3 × 3.000 = 900 USDT'dir; teminata göre bu yaklaşık yüzde 31 eder. Pozisyonu kapatmazsanız ve fiyat 57.000'e dönerse aynı ekran 300 USDT gerçekleşmemiş zarar gösterir. 61.000'den kapatsaydınız, yüzde 0,05 kapanış ücreti olan yaklaşık 9 USDT düşüldükten sonra 891 USDT gerçekleşmiş kâr elde ederdiniz."],"mistakes":["Gerçekleşmemiş kârı cebinizdeki para gibi görüp kâr al veya stop planı yapmamak.","Kaldıraçlı pozisyonda teminata göre yüzdeyi pozisyon değerine göre getiri sanmak.","Çapraz marjinde bir pozisyonun kâğıt üzerindeki kârına dayanarak yeni yüksek kaldıraçlı pozisyonlar açmak."],"faq":[{"q":"Gerçekleşmemiş ve gerçekleşmiş kâr farkı nedir?","a":"Gerçekleşmemiş kâr, açık pozisyonun anlık değeridir ve fiyatla değişir. Gerçekleşmiş kâr ise pozisyon kapatıldıktan sonra kesinleşen ve bakiyenize eklenen tutardır."},{"q":"Gerçekleşmemiş kârı çekebilir miyim?","a":"Genellikle hayır, önce pozisyonu kapatıp kârı gerçekleştirmeniz gerekir. Bazı borsalar çapraz marjinde gerçekleşmemiş kârın teminat olarak kullanılmasına izin verir, ama çekilmesine izin vermez."}],"title":"Gerçekleşmemiş kâr/zarar (unrealized PnL) nedir?","description":"Gerçekleşmemiş kâr-zararın nasıl hesaplandığını, teminatı nasıl etkilediğini ve gerçekleşmiş kârdan farkını öğrenin.","related":[["mark-price","İşaret fiyatı (Mark price)","İşaret fiyatı (mark price), vadeli işlem borsalarının gerçekleşmemiş kâr-zararı ve likidasyonu hesaplamak için kullandığı, manipülasyona karşı dengelenmiş adil fiyattır."],["cross-margin","Çapraz marjin (Cross margin)","Çapraz marjin, hesaptaki kullanılabilir bakiyenin tamamının tüm açık pozisyonlar için ortak teminat olarak kullanıldığı marjin modudur."],["liquidation-price","Likidasyon fiyatı (Liquidation price)","Likidasyon fiyatı, kaldıraçlı bir pozisyonun teminatının bakım seviyesine indiği ve borsanın pozisyonu zorla kapatmaya başladığı işaret fiyatı seviyesidir."],["take-profit","Kâr al (take-profit) emri","Kâr al (take-profit) emri, fiyat önceden belirlediğiniz hedef seviyeye ulaştığında pozisyonunuzu otomatik olarak kapatarak kârı gerçekleştiren emirdir."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Teminatınız sıfıra ulaşmadan önce pozisyonunuz neden kapatılabilir?"},"coin":null,"tool":null,"cta":false},"cold-wallet":{"slug":"cold-wallet","cat":"wallets-security","en":"Cold wallet (cold storage)","contentLocale":"tr","term":"Soğuk cüzdan (cold wallet)","aka":["cold wallet","soğuk depolama","cold storage","çevrim dışı cüzdan"],"short":"Soğuk cüzdan, özel anahtarları internete hiç bağlanmayan bir cihazda veya ortamda saklayarak uzaktan çalınma riskini büyük ölçüde azaltan kripto saklama yöntemidir.","body":["Soğuk depolamanın temel fikri, işlemi imzalayan anahtarın çevrim dışı kalmasıdır. Bunun en yaygın biçimi donanım cüzdanlarıdır; ayrıca hiç internete bağlanmamış bir bilgisayar veya kâğıt cüzdan gibi yöntemler de kullanılır.","Soğuk cüzdanla para almak için yalnızca adresinizi paylaşmanız yeterlidir; anahtar gerekmez. Para göndermek istediğinizde işlem çevrim dışı cihazda imzalanır ve sadece imzalı işlem ağa iletilir. Böylece bilgisayarınızdaki bir virüs anahtarı doğrudan okuyamaz.",["Soğuk cüzdan her riski çözmez. ",["Kurtarma ifadesi","seed-phrase"]," kâğıtta açıkta duruyorsa, ya da sahte bir işlemi okumadan onaylarsanız fonlar yine kaybolabilir. Ayrıca her transferde cihazı bağlamak gerektiği için sık işlem yapanlar için yavaştır. Bu yüzden genellikle uzun vadeli birikim için tercih edilir."]],"example":["0,8 ",["BTC","bitcoin"],"'yi uzun vadeli tutmak istediğinizi varsayalım. Bunu borsadan donanım cüzdanınızın Bitcoin adresine çekersiniz. Aylarca hiçbir işlem yapmasanız da bakiyeyi bir blok gezgininde adresinizi aratarak görebilirsiniz. İki yıl sonra 0,1 BTC satmak istediğinizde cihazı bağlar, işlemi cihaz ekranında kontrol edip onaylar ve 0,1 BTC'yi borsaya gönderirsiniz; kalan 0,7 BTC yine çevrim dışı anahtarla korunmaya devam eder."],"mistakes":["Kurtarma ifadesini fotoğraflayıp telefonda saklamak, soğuk depolamanın amacını boşa çıkarır.","Tek bir kâğıt yedek tutmak ve yangın, su baskını gibi riskleri hesaba katmamak.","İşlemi cihaz ekranındaki adres ve tutarı kontrol etmeden onaylamak."],"faq":[{"q":"Soğuk cüzdan ile donanım cüzdanı aynı şey mi?","a":"Donanım cüzdanı soğuk cüzdanın en yaygın türüdür. Ancak kâğıt cüzdan veya hiç internete bağlanmamış bir bilgisayar da soğuk depolama sayılabilir."},{"q":"Soğuk cüzdandaki kripto internet olmadan kaybolur mu?","a":"Hayır. Varlıklar blokzincirde kayıtlıdır; cihaz yalnızca anahtarı saklar. Cihaz bozulsa bile kurtarma ifadesiyle erişimi geri kazanabilirsiniz."}],"title":"Soğuk cüzdan (cold wallet) nedir? Soğuk depolama anlamı","description":"Soğuk cüzdanın nasıl çalıştığını, sıcak cüzdandan farkını ve uzun vadeli saklamada nelere dikkat etmeniz gerektiğini öğrenin.","related":[["hot-wallet","Sıcak cüzdan (hot wallet)","Sıcak cüzdan, özel anahtarları internete bağlı bir cihazda veya sunucuda tutulan, bu sayede hızlı işlem yapmaya uygun ama çevrim dışı saklamaya göre daha fazla saldırıya açık olan kripto cüzdanıdır."],["hardware-wallet","Donanım cüzdanı (hardware wallet)","Donanım cüzdanı, özel anahtarları güvenli bir çip içinde çevrim dışı saklayan ve işlemleri cihazın kendi ekranında onaylatarak imzalayan küçük bir fiziksel cihazdır."],["seed-phrase","Kurtarma ifadesi (seed phrase)","Kurtarma ifadesi (seed phrase), bir kripto cüzdanının tüm özel anahtarlarının türetildiği 12 veya 24 kelimelik listedir ve bu kelimeleri bilen herkes cüzdanın tamamını kontrol edebilir."],["multisig-wallet","Çoklu imza cüzdanı (multisig)","Çoklu imza (multisig) cüzdanı, bir işlemin gerçekleşmesi için birden fazla özel anahtarın onayını gerektiren, örneğin 3 anahtardan 2'sinin imzasını isteyen kripto cüzdanıdır."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin'lerim nerede? Borsa ve cüzdan farkı"},"coin":null,"tool":null,"cta":false},"rug-pull":{"slug":"rug-pull","cat":"wallets-security","en":"Rug pull","contentLocale":"tr","term":"Rug pull (halı çekme)","aka":["rug pull","halı çekme","çıkış dolandırıcılığı","exit scam"],"short":"Rug pull, bir kripto projesinin geliştiricilerinin yatırımcı parasını toplayıp likiditeyi çekerek, token'ları satarak veya akıllı sözleşmedeki gizli yetkileri kullanarak projeyi aniden terk ettiği dolandırıcılıktır.","body":[["En yaygın türü ",["likidite","liquidity"]," çekmektir: geliştirici bir ",["DEX","dex"],"'te token ile ",["ETH","ethereum"]," veya ",["USDT","usdt"]," eşleştirip ",["likidite havuzu","liquidity-pool"]," açar, insanlar token'ı aldıkça havuzda değerli varlık birikir. Sonra geliştirici havuzdaki likiditeyi geri çeker ve token'ın fiyatı neredeyse sıfıra düşer."],"Diğer türler arasında ekibin büyük token payını piyasaya boşaltması ve sözleşmedeki gizli fonksiyonlar vardır. Örneğin bir \"honeypot\" token'ı almanıza izin verir ama satmanızı engeller; bazı sözleşmelerde sahibi sınırsız token basabilir veya transfer vergisini yüzde 100'e çıkarabilir.","Bazı kontroller riski azaltır: likiditenin kilitli olup olmadığına, sözleşmenin doğrulanmış ve denetlenmiş olmasına, sahiplik yetkilerine, token dağılımının birkaç cüzdanda yoğunlaşıp yoğunlaşmadığına bakmak. Bu kontroller garanti vermez ama en bariz tuzakları eler."],"example":["Yeni bir ",["memecoin","memecoin"],"'in havuzunda 50 ETH ve 10 milyon token olduğunu varsayalım; fiyat token başına yaklaşık 0,000005 ETH. Siz 1 ETH ile token alıyorsunuz. Birkaç gün sonra geliştirici havuzdaki tüm likiditeyi çekiyor. Havuzda neredeyse hiç ETH kalmadığı için token'larınızı satmak istediğinizde 1 ETH'lik pozisyonunuz için yalnızca çok küçük bir miktar alabiliyorsunuz. Likidite kilitli olsaydı bu hamle o süre içinde mümkün olmazdı."],"mistakes":["Sosyal medyadaki heyecana bakıp sözleşmeyi hiç incelemeden token almak.","Satış yapılabildiğini küçük bir test işlemiyle kontrol etmemek.","Arzın büyük kısmının birkaç cüzdanda olduğunu görmezden gelmek."],"faq":[{"q":"Rug pull yasal mı?","a":"Yatırımcıları kasıtlı olarak aldatmak birçok ülkede dolandırıcılık sayılabilir, ancak hukuki sonuç ülkeye ve olayın ayrıntılarına göre değişir. Anonim ekipler nedeniyle paranın geri alınması nadirdir."},{"q":"Likidite kilidi rug pull'u tamamen önler mi?","a":"Hayır. Likiditeyi çekmeyi geciktirir, ancak ekip token dökebilir veya sözleşmedeki başka yetkileri kullanabilir."}],"title":"Rug pull nedir? Kripto çıkış dolandırıcılığı anlamı","description":"Rug pull'un türlerini, likidite çekme ve honeypot tuzaklarını ve yeni bir token almadan önce neleri kontrol edeceğinizi öğrenin.","related":[["memecoin","Memecoin","Memecoin, bir internet şakası, hayvan figürü veya popüler kültür öğesinden ilham alan, değeri büyük ölçüde topluluk ilgisine ve spekülasyona dayanan bir kripto paradır; Dogecoin ve Shiba Inu en bilinen örneklerdir."],["liquidity-pool","Likidite havuzu (liquidity pool)","Likidite havuzu, kullanıcıların yatırdığı iki veya daha fazla token'ın bir akıllı sözleşmede kilitlendiği ve DEX'lerde takasların doğrudan bu havuzdan yapıldığı fon havuzudur."],["token-approval","Token onayı (token approval / allowance)","Token onayı, cüzdanınızdaki belirli bir token'ı sizin adınıza harcayabilmesi için bir akıllı sözleşmeye verdiğiniz izindir ve sınırsız verilen onaylar istismar edilirse cüzdanınızı boşaltabilir."],["dex","Merkeziyetsiz borsa (DEX)","Merkeziyetsiz borsa (DEX), kullanıcıların kendi cüzdanlarından, bir şirkete fon emanet etmeden, akıllı sözleşmeler aracılığıyla kripto takası yaptığı borsadır."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Biri sana para kazandıracağını söylüyor. Önce ne istediğine bak."},"coin":null,"tool":"/topics/meme-coins","cta":false},"oracle":{"slug":"oracle","cat":"defi","en":"Blockchain oracle","contentLocale":"tr","term":"Blokzincir oracle'ı (kâhin)","aka":["oracle","kâhin","fiyat oracle'ı","price oracle"],"short":"Blokzincir oracle'ı, fiyatlar veya hava durumu gibi blokzincir dışındaki verileri akıllı sözleşmelere güvenilir biçimde taşıyan hizmettir; DeFi protokolleri teminat ve tasfiye hesaplarında bu verilere dayanır.","body":[["Akıllı sözleşmeler kendi başlarına internetten veri çekemez. Bir borç verme protokolünün ",["ETH","ethereum"],"'nin fiyatını bilmesi için bu verinin zincire yazılması gerekir. Chainlink gibi oracle ağları, birçok bağımsız veri sağlayıcıdan fiyat toplayıp bir ortalama oluşturur ve bunu düzenli olarak zincire yazar."],["Oracle'lar ",["DeFi","defi"],"'nin kritik altyapısıdır: teminat değeri, tasfiye kararları, sentetik varlıklar ve vadeli işlem platformlarının fonlama hesapları bu verilere bağlıdır. Yanlış bir fiyat, sağlıklı pozisyonların haksız yere tasfiye edilmesine veya bir protokolün boşaltılmasına yol açabilir."],["En bilinen risk oracle manipülasyonudur. Bir protokol fiyatı tek bir düşük likiditeli ",["DEX","dex"]," havuzundan okuyorsa, saldırgan flaş krediyle o havuzun fiyatını anlık olarak bozabilir. Bu yüzden iyi tasarlanmış protokoller birden çok kaynak, zaman ağırlıklı ortalama fiyatlar ve sapma limitleri kullanır."]],"example":["Bir borç verme protokolünde 1 ETH teminatla 1.500 ",["USDC","usdc"]," borç aldığınızı ve tasfiye eşiğinin ETH fiyatı 1.875 USDC olduğunu varsayalım. Gerçek piyasada ETH 2.400 USDC. Protokol fiyatı tek bir küçük havuzdan okuyorsa, bir saldırgan o havuzda fiyatı birkaç saniyeliğine 1.800 USDC'ye indirebilir ve pozisyonunuz haksız yere tasfiye olabilir. Birden çok kaynağın ortalamasını kullanan bir oracle bu tek havuzdaki sapmayı büyük ölçüde filtreler."],"mistakes":["Bir protokolün hangi oracle'ı kullandığını hiç kontrol etmemek.","Oracle fiyatının her an borsa fiyatıyla birebir aynı olduğunu sanmak.","Düşük likiditeli token'ları teminat olarak kullanmanın oracle riskini artırdığını göz ardı etmek."],"faq":[{"q":"Oracle problemi nedir?","a":"Merkeziyetsiz bir sistemin dış dünyadan gelen veriye güvenmek zorunda olmasıdır. Veri kaynağı manipüle edilirse sözleşme kusursuz çalışsa bile yanlış sonuç üretir."},{"q":"Chainlink ne yapar?","a":"Birden fazla bağımsız düğümden veri toplayarak fiyat ve diğer bilgileri akıllı sözleşmelere sağlayan bir oracle ağıdır. Birçok DeFi protokolü fiyat verisi için onu kullanır."}],"title":"Oracle nedir? Blokzincir kâhini ne işe yarar?","description":"Blokzincir oracle'larının dış verileri akıllı sözleşmelere nasıl taşıdığını ve oracle manipülasyonu riskini öğrenin.","related":[["smart-contract","Akıllı kontrat (smart contract)","Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır."],["defi-lending","DeFi borç verme (DeFi lending)","DeFi borç verme, kullanıcıların kripto varlıklarını akıllı sözleşme havuzlarına yatırarak faiz kazandığı, başkalarının da bu havuzlardan teminat göstererek borç aldığı merkeziyetsiz kredi sistemidir."],["index-price","Endeks fiyatı (Index price)","Endeks fiyatı, bir varlığın birden fazla büyük spot borsadaki fiyatlarının ağırlıklı ortalamasından hesaplanan ve vadeli kontratlar için referans olarak kullanılan fiyattır."],["flash-loan","Flaş kredi (flash loan)","Flaş kredi, teminat gerektirmeyen ama aynı blokzincir işlemi içinde alınıp geri ödenmesi zorunlu olan bir DeFi borcudur; geri ödenmezse tüm işlem iptal edilir."]],"lesson":null,"coin":{"slug":"chainlink","name":"Chainlink","symbol":"LINK"},"tool":null,"cta":false},"launchpad":{"slug":"launchpad","cat":"exchange-features","en":"Launchpad (token sale)","contentLocale":"tr","term":"Launchpad (token satışı)","aka":["launchpad","token satış platformu","IEO"],"short":"Launchpad, bir borsanın veya platformun yeni bir projenin token'larını listelemeden önce kullanıcılara belirli bir fiyattan sattığı token satış platformudur; borsa üzerinden yapılan satışa IEO da denir.","body":[[["Launchpool","launchpool"],"'da token'ı ücretsiz ödül olarak alırsınız; launchpad'de ise satın alırsınız. Katılım için çoğu zaman borsa token'ı tutmanız, belirli bir süre bakiyenizin ortalamasının hesaplanması ve ",["KYC","kyc"]," gerekir. Talep yüksek olduğunda dağıtım piyango veya oranlı tahsis ile yapılır."],"Oranlı tahsiste herkes istediği kadar taahhüt eder, ama satış fazla talep görürse herkese talebin bir kısmı verilir ve kalan para iade edilir. Token'ların bir kısmı hemen, kalanı belirli takvimle (vesting) açılabilir.",["Satış fiyatının ",["listeleme","token-listing"]," fiyatından düşük olacağı garanti değildir. Ayrıca projenin token açılış takvimi, ekip ve yatırımcı payları ve ",["dolaşımdaki arz","circulating-supply"]," miktarı fiyatı güçlü şekilde etkileyebilir."]],"example":["Bir launchpad satışında token fiyatının 0,05 ",["USDT","usdt"]," ve toplam satış miktarının 500.000 USDT olduğunu varsayalım. Kullanıcılar toplam 25.000.000 USDT taahhüt eder; talep satışın 50 katıdır. Siz 2.000 USDT taahhüt ettiyseniz yalnızca 40 USDT'lik tahsis alırsınız, yani 800 token. Kalan 1.960 USDT iade edilir. Token 0,08 USDT'den listelenirse 800 token 64 USDT eder ve 24 USDT kâr görünür; 0,03'ten listelenirse 800 token 24 USDT eder ve 16 USDT zarar olur."],"mistakes":["Taahhüt ettiğiniz tutarın tamamının token'a çevrileceğini sanmak.","Token açılış takvimini ve dolaşımdaki arzı incelemeden katılmak.","Sahte launchpad sitelerine veya 'erken satış' vaat eden mesajlara para göndermek."],"faq":[{"q":"Launchpad ile launchpool farkı nedir?","a":"Launchpad'de yeni token'ları belirli bir fiyattan satın alırsınız. Launchpool'da ise varlıklarınızı havuzda tutarak token'ları ödül olarak kazanırsınız."},{"q":"Launchpad'e katılmak için ne gerekir?","a":"Genellikle KYC'li bir hesap ve programın istediği varlıktan belirli bir bakiye gerekir. Kurallar her satış için ayrı duyurulur."}],"title":"Launchpad nedir? Kripto token satışı ve IEO","description":"Launchpad nedir, borsalardaki token satışlarında tahsis nasıl hesaplanır ve launchpool'dan farkı nedir, sayısal örnekle öğrenin.","related":[["launchpool","Launchpool","Launchpool, borsanın belirli coin'leri veya stablecoin'leri havuzda kilitleyen kullanıcılara, yeni listelenecek bir projenin token'larını belirli bir süre boyunca ücretsiz dağıttığı programdır."],["token-listing","Token listelemesi","Token listelemesi, bir kripto varlığın bir borsada işlem çiftleriyle alınıp satılabilir hâle getirilmesi, yani borsanın o token için yatırma, çekim ve işlem hizmeti açmasıdır."],["token-unlock","Token kilit açılımı (token unlock)","Token kilit açılımı (token unlock), ekip, yatırımcılar veya ekosistem fonu için önceden kilitlenmiş token'ların belirlenmiş bir takvime göre serbest bırakılıp alınıp satılabilir hale gelmesidir."],["airdrop","Airdrop","Airdrop, bir projenin token'larını belirli koşulları sağlayan cüzdanlara veya kullanıcılara ücretsiz olarak dağıtmasıdır; genellikle erken kullanıcıları ödüllendirmek ve token'ı geniş bir kitleye yaymak amacıyla yapılır."]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"sub-account":{"slug":"sub-account","cat":"exchange-features","en":"Sub-account","contentLocale":"tr","term":"Alt hesap (sub-account)","aka":["sub-account","alt hesap","yan hesap"],"short":"Alt hesap, ana borsa hesabınıza bağlı, ayrı bakiyesi, ayrı API anahtarları ve ayrı risk ayarları olan ek bir hesaptır; stratejileri ve riskleri birbirinden ayırmak için kullanılır.","body":[["Ana hesap bir kez ",["KYC","kyc"],"'den geçer, altına birden fazla alt hesap açılabilir. Her alt hesabın kendi bakiyesi vardır ve aralarında ücretsiz iç transfer yapabilirsiniz. Alt hesap sayısı ve özellikleri borsaya ve VIP seviyesine göre değişir."],["En yaygın kullanım riski ayırmaktır. Örneğin uzun vadeli spot birikiminizi ana hesapta, kaldıraçlı vadeli işlemleri bir alt hesapta, bot veya kopya işlemi başka bir alt hesapta tutabilirsiniz. Bir alt hesapta ",["likidasyon","liquidation"]," olsa bile diğerleri etkilenmez."],"API ile çalışan botlar için de faydalıdır: her bota kendi alt hesabını ve sadece işlem yetkisi olan, çekim yetkisi kapalı bir API anahtarı verirsiniz. Ana hesabın güvenliği, iki faktörlü doğrulama ve çekim adres listesi ile korunmalıdır."],"example":["Toplam 12.000 ",["USDT","usdt"],"'niz olduğunu varsayalım. 8.000 USDT'yi ana hesapta spot ",["BTC","bitcoin"]," olarak tutar, 3.000 USDT'yi vadeli işlem alt hesabına, 1.000 USDT'yi grid botu alt hesabına aktarırsınız. Vadeli alt hesapta 10 kat kaldıraçlı bir pozisyon ters gider ve 3.000 USDT'nin tamamı likide olur. Kaybınız bu alt hesapla sınırlı kalır; ana hesaptaki 8.000 USDT'lik BTC ve bot hesabındaki 1.000 USDT etkilenmez."],"mistakes":["Bot API anahtarlarına çekim yetkisi vermek.","Alt hesap bakiyelerini ayrı takip etmeyip toplam riski gözden kaçırmak.","Tüm alt hesapları aynı yüksek riskli stratejiyle kullanıp ayırmanın faydasını yok etmek."],"faq":[{"q":"Alt hesap için ayrıca KYC gerekir mi?","a":"Genellikle hayır; alt hesaplar ana hesabın KYC'sine bağlıdır. Kurallar ve alt hesap sayısı borsaya göre değişebilir."},{"q":"Alt hesaplar arası transfer ücretli mi?","a":"Çoğu borsada aynı ana hesaba bağlı alt hesaplar arasındaki transferler iç transfer sayılır ve ücretsizdir. Zincir üstünde işlem yapılmadığı için anında gerçekleşir."}],"title":"Alt hesap (sub-account) nedir? Neden kullanılır","description":"Borsada alt hesap (sub-account) nedir, riskleri ayırmak ve botlar için nasıl kullanılır ve güvenli API ayarları nelerdir, öğrenin.","related":[["unified-trading-account","Birleşik işlem hesabı (UTA)","Birleşik işlem hesabı (UTA), spot, vadeli ve opsiyon gibi farklı ürünleri tek bir hesapta toplayıp tüm bakiyenizi ortak teminat olarak kullanmanıza izin veren borsa hesap yapısıdır."],["isolated-margin","İzole marjin (Isolated margin)","İzole marjin, her pozisyona ayrı bir teminat ayrıldığı ve olası kaybın yalnızca o pozisyona bağlanan teminatla sınırlı kaldığı marjin modudur."],["two-factor-authentication","İki faktörlü doğrulama (2FA)","İki faktörlü doğrulama (2FA), hesabınıza girişte veya çekimde şifrenin yanında ikinci bir kanıt, örneğin bir doğrulama uygulamasından gelen 6 haneli kod istenmesini sağlayan güvenlik katmanıdır."],["copy-trading","Kopya işlem (copy trading)","Kopya işlem (copy trading), seçtiğiniz bir trader'ın açtığı ve kapattığı pozisyonların, belirlediğiniz tutar ve oranla sizin hesabınızda otomatik olarak tekrarlanmasıdır."]],"lesson":null,"coin":null,"tool":null,"cta":false},"vip-tier":{"slug":"vip-tier","cat":"exchange-features","en":"VIP fee tier","contentLocale":"tr","term":"VIP ücret seviyesi","aka":["VIP seviye","VIP tier","ücret seviyesi","komisyon kademesi"],"short":"VIP ücret seviyesi, borsaların 30 günlük işlem hacminize veya hesap bakiyenize göre sizi kademelere ayırıp daha yüksek kademede daha düşük maker ve taker ücreti uyguladığı sistemdir.","body":["Her borsanın bir ücret tablosu vardır. En alt seviye normal kullanıcı seviyesidir. Son 30 günlük spot veya vadeli hacminiz belirli bir eşiği geçtiğinde ya da varlık bakiyeniz belirli bir tutara ulaştığında bir üst seviyeye çıkarsınız ve ücretleriniz düşer.","Seviye genellikle günlük olarak yeniden hesaplanır. Hacminiz düşerse seviyeniz de düşer. Spot ve vadeli seviyeler bazı borsalarda ayrı, bazılarında birlikte hesaplanır. Bazı borsalar borsa token'ı tutanlara ek indirim de verir.","Küçük ve orta ölçekli trader'lar için VIP seviyesine ulaşmak çoğu zaman zordur; bu yüzden maker emir kullanmak veya referans iadesi almak maliyeti düşürmenin daha erişilebilir yollarıdır. Güncel eşikleri her zaman borsanın ücret sayfasından kontrol edin."],"example":["Bir borsada normal seviyede vadeli taker ücretinin yüzde 0,05, VIP 1 seviyesinde yüzde 0,04 olduğunu ve VIP 1 için 30 günlük hacmin 5 milyon ",["USDT","usdt"]," gerektirdiğini varsayalım. Siz ayda 6 milyon USDT hacim yapıyorsanız normal seviyede 3.000 USDT, VIP 1'de 2.400 USDT ücret ödersiniz; aylık fark 600 USDT'dir. Ama ayda 1 milyon USDT hacim yapan biri için VIP 1'e ulaşmak, ek 4 milyon USDT hacim ve onun ücreti demektir; bu da hedefi anlamsız kılar."],"mistakes":["Sadece VIP seviyesine çıkmak için gereksiz işlem yapmak.","Seviyenin kalıcı olduğunu sanmak; hacim düşünce seviye de düşer.","Spot ve vadeli seviyelerin aynı şekilde hesaplandığını varsaymak."],"faq":[{"q":"VIP seviyesi nasıl yükseltilir?","a":"Genellikle son 30 günlük işlem hacminizi artırarak veya hesabınızdaki varlık bakiyesini belirli bir seviyeye çıkararak. Eşikler borsaya göre değişir."},{"q":"VIP seviyem ne zaman güncellenir?","a":"Çoğu borsa seviyeyi her gün belirli bir saatte yeniden hesaplar. Seviye düştüğünde daha yüksek ücret tablosu otomatik uygulanır."}],"title":"VIP seviyesi nedir? Borsa ücret kademeleri","description":"Kripto borsalarında VIP ücret seviyesi nedir, 30 günlük hacim ve bakiye ücretinizi nasıl düşürür ve hedeflemeye değer mi, öğrenin.","related":[["maker-taker-fees","Maker ve taker ücretleri","Maker ve taker ücretleri, borsanın emir defterine likidite ekleyen (maker) ve defterdeki emirleri anında karşılayarak likidite çeken (taker) işlemlere uyguladığı farklı komisyon oranlarıdır."],["referral-code","Referans kodu (komisyon iadesi)","Referans kodu, bir borsaya kaydolurken girilen ve sizi davet eden kişi veya ortakla eşleştiren; çoğu zaman işlem ücretlerinizin bir kısmının size geri ödenmesini sağlayan davet kodudur."],["trading-volume","İşlem hacmi (Trading volume)","İşlem hacmi, belirli bir sürede, genellikle 24 saatte, bir varlığın ne kadarının alınıp satıldığını gösteren toplam miktardır."],["market-maker","Piyasa yapıcı (Market maker)","Piyasa yapıcı, emir defterinde sürekli alış ve satış emirleri vererek likidite sağlayan ve kazancını çoğunlukla alış-satış makasından elde eden kişi veya şirkettir."]],"lesson":null,"coin":null,"tool":"/rates","cta":false},"token-listing":{"slug":"token-listing","cat":"exchange-features","en":"Token listing","contentLocale":"tr","term":"Token listelemesi","aka":["listeleme","token listing","borsada listelenme","yeni listeleme"],"short":"Token listelemesi, bir kripto varlığın bir borsada işlem çiftleriyle alınıp satılabilir hâle getirilmesi, yani borsanın o token için yatırma, çekim ve işlem hizmeti açmasıdır.","body":[["Borsa bir token'ı listelemeden önce genellikle projenin teknik yapısını, güvenliğini, likiditesini, yasal durumunu ve topluluk ilgisini değerlendirir. Listeleme duyurusunda yatırma açılış zamanı, işlem başlangıç saati ve işlem çiftleri (örneğin XYZ/",["USDT","usdt"],") belirtilir."],["Büyük borsalarda listeleme, token'ın daha fazla kullanıcıya ulaşmasını sağlar ve ilk saatlerde çok yüksek ",["oynaklık","volatility"]," yaratabilir. Bazı borsalar yeni token'ları önce 'gözlem' veya 'yenilik' bölgesi gibi ayrı bir etiketle listeler ve ek risk uyarısı gösterir."],["Listeleme bir kalite garantisi değildir. Token'ın toplam arzı, dolaşımdaki miktarı ve yakın tarihli kilit açılışları fiyatı güçlü şekilde etkiler. İlk dakikalarda ",["piyasa emri","market-order"]," vermek de yüksek ",["kayma","slippage"]," ile sonuçlanabilir."]],"example":["Yeni listelenen bir token'ın ilk dakikada 0,20 USDT'den işlem gördüğünü, emir defterinin ise çok ince olduğunu varsayalım. 1.000 USDT'lik piyasa emri verirsiniz. Satış tarafında 0,20 ile 0,26 arasında dağınık emirler olduğu için ortalama alım fiyatınız 0,24 olur ve yaklaşık 4.167 token alırsınız. Fiyat bir saat sonra 0,18'e oturursa token'larınız 750 USDT eder ve 250 USDT zararla başlarsınız. ",["Limit emir","limit-order"]," kullansaydınız ortalama fiyatınızı kontrol edebilirdiniz."],"mistakes":["Büyük bir borsada listelenmeyi projenin güvenilir olduğunun kanıtı saymak.","Listeleme anında ince emir defterine büyük piyasa emri vermek.","Token'ın kilit açılış takvimini ve dolaşımdaki arzını incelememek."],"faq":[{"q":"Token listelenince fiyat yükselir mi?","a":"Bazen kısa süreli sert yükselişler olur, bazen listeleme sonrasında satış baskısı fiyatı düşürür. Sonuç arz yapısına, talebe ve piyasa koşullarına bağlıdır."},{"q":"Listeleme duyurusunu nereden takip ederim?","a":"Borsanın resmi duyuru sayfasından ve doğrulanmış sosyal medya hesaplarından. Sahte listeleme duyuruları dolandırıcılıkta sık kullanılır."}],"title":"Token listelemesi nedir? Borsada yeni coin işlemleri","description":"Token listelemesi nedir, borsalar coin'leri neye göre listeler ve yeni listelemelerde kayma ile oynaklık riski nasıl yönetilir.","related":[["delisting","Delisting (borsadan çıkarma)","Delisting, bir borsanın bir token'ın veya işlem çiftinin alım satımını durdurup ardından yatırma ve çekim hizmetlerini de kapatarak o varlığı platformdan kaldırmasıdır."],["launchpool","Launchpool","Launchpool, borsanın belirli coin'leri veya stablecoin'leri havuzda kilitleyen kullanıcılara, yeni listelenecek bir projenin token'larını belirli bir süre boyunca ücretsiz dağıttığı programdır."],["liquidity","Likidite (Liquidity)","Likidite, bir varlığın fiyatı fazla etkilenmeden ne kadar hızlı ve kolay alınıp satılabildiğini gösteren ölçüdür."],["altcoin","Altcoin","Altcoin, Bitcoin dışındaki tüm kripto paralar için kullanılan genel bir terimdir; Ethereum ve Solana gibi büyük ağlardan küçük proje token'larına ve memecoin'lere kadar geniş bir yelpazeyi kapsar."]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"stock-perpetuals":{"slug":"stock-perpetuals","cat":"tokenized-assets","en":"Stock perpetuals","contentLocale":"tr","term":"Hisse senedi sürekli vadelileri (stock perpetuals)","aka":["stock perpetuals","hisse perp","hisse sürekli vadeli kontratı"],"short":"Hisse senedi sürekli vadelileri, bir hissenin fiyatını takip eden, vadesi olmayan ve genellikle USDT ile teminatlandırılan, kaldıraçla long veya short açılabilen kripto borsası türev kontratlarıdır.","body":[["Bu kontratlarda hisseye veya bir token'a sahip olmazsınız. Sadece fiyat farkı üzerine işlem yaparsınız. Kripto sürekli vadelilerde olduğu gibi ",["fonlama oranı","funding-rate"]," vardır: long ve short taraf arasında periyodik ödemeler yapılarak kontrat fiyatı hisse fiyatına yakın tutulur."],["Tokenize hisseden farkı şudur: ",["tokenize hisse","tokenized-stocks"]," varlığın kendisini temsil etmeye çalışır, sürekli vadeli ise sadece fiyat maruziyeti verir. Vadeli kontratta ",["kaldıraç","leverage"]," kullanabilir ve kolayca short açabilirsiniz, ama ",["likidasyon","liquidation"]," riski de doğar."],"Hisse piyasası kapalıyken bu kontratların fiyatı nasıl belirlendiği borsaya göre değişir. Bazıları işlemi durdurur, bazıları dahili fiyatla devam eder. Açılışta oluşan fiyat boşlukları kaldıraçlı pozisyonlarda beklenmedik likidasyonlara yol açabilir. Kontrat şartnamesini okumak burada özellikle önemlidir."],"example":["Hisse fiyatı 100 dolar olan bir şirketin sürekli vadeli kontratında 5 kat kaldıraçla 400 ",["USDT","usdt"]," teminatla long açtığınızı varsayalım. ",["Pozisyon büyüklüğü","position-sizing"]," 2.000 USDT, yani 20 kontrat birimidir. Fiyat 110 dolara çıkarsa 200 USDT kazanırsınız; teminatınıza göre yüzde 50. Fonlama oranı 8 saatte bir yüzde 0,01 ise her ödemede yaklaşık 0,2 USDT ödersiniz. Hisse kötü bir bilanço sonrası 82 dolardan açılırsa zarar 360 USDT olur ve likidasyon eşiği aşıldığı için pozisyon büyük ihtimalle kapanır."],"mistakes":["Hisse perp'inin size hisse veya temettü hakkı verdiğini sanmak.","Bilanço ve haftalık açılış boşluklarını hesaba katmadan yüksek kaldıraç kullanmak.","Piyasa kapalıyken fiyatın nasıl belirlendiğini kontrat şartnamesinden öğrenmemek."],"faq":[{"q":"Hisse perp ile tokenize hisse farkı nedir?","a":"Tokenize hisse varlığın kendisini temsil eden bir token'dır. Hisse perp ise sadece fiyat üzerine kaldıraçlı işlem yapmanızı sağlayan, vadesi olmayan bir türev kontrattır."},{"q":"Hisse sürekli vadelilerinde fonlama oranı var mı?","a":"Evet, kripto sürekli vadelilerinde olduğu gibi fonlama oranı vardır. Ödeme sıklığı ve hesaplama yöntemi borsaya göre değişebilir."}],"title":"Hisse perp nedir? Hisse senedi sürekli vadelileri","description":"Hisse senedi sürekli vadeli kontratları nedir, tokenize hisseden farkı nedir ve açılış boşlukları likidasyon riskini nasıl artırır.","related":[["tokenized-stocks","Tokenize hisse senetleri","Tokenize hisse senetleri, bir şirketin hisse senedinin fiyatını takip eden ve genellikle bir saklayıcıda tutulan gerçek hisseyle desteklenen, blockchain üzerinde işlem gören token'lardır."],["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır."],["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
